    let (mut slow, mut fast) = (next[0], next[next[0]]);
    while slow != fast {
        slow = next[slow];
        fast = next[next[fast]];
    }
    slow = 0;
    while slow != fast {
        slow = next[slow];
        fast = next[fast];
    }
    slow
}

