fn csv<T: std::fmt::Display>(a: impl IntoIterator<Item = T>) -> String {
    a.into_iter()
        .map(|x| x.to_string())
        .collect::<Vec<_>>()
        .join(",")
}

fn insertion_sort_by_key<T: Clone, K: Ord>(values: &mut [T], key: impl Fn(&T) -> K) {
    for i in 1..values.len() {
        let value = values[i].clone();
        let mut j = i;
        // A strict comparison leaves an equal earlier key in front.
        while j > 0 && key(&values[j - 1]) > key(&value) {
            values[j] = values[j - 1].clone();
            j -= 1;
        }
        values[j] = value;
    }
}
fn insertion_sort(values: &mut [i32]) {
    insertion_sort_by_key(values, |x| *x);
}

fn main() {
    let result = {
        let mut values = vec![5, 2, 4, 6, 1, 3];
        insertion_sort(&mut values);
        csv(values)
    };
    println!("{result}");
}

