    let result = stable_merge_sort(&[(2, 'a'), (1, 'x'), (2, 'b'), (1, 'y')])
        .iter()
        .map(|(k, v)| format!("{k}{v}"))
        .collect::<Vec<_>>()
        .join(",");
    println!("{result}");
}

