fn quicksort(a: &mut [i32]) {
    if a.len() < 2 {
        return;
    }
    let pivot = a[a.len() / 2];
    let (mut low, mut i, mut high) = (0, 0, a.len());
    while i < high {
        if a[i] < pivot {
            a.swap(low, i);
            low += 1;
            i += 1;
        } else if a[i] > pivot {
            high -= 1;
            a.swap(i, high);
        } else {
            i += 1;
        }
    }
    quicksort(&mut a[..low]);
    quicksort(&mut a[high..]);
}

