fn merge_lists(mut a: Link, mut b: Link) -> Link {
    let mut out = None;
    let mut tail = &mut out;
    while a.is_some() && b.is_some() {
        let chosen = if a.as_ref().unwrap().value <= b.as_ref().unwrap().value {
            &mut a
        } else {
            &mut b
        };
        let mut node = chosen.take().unwrap();
        *chosen = node.next.take();
        *tail = Some(node);
        tail = &mut tail.as_mut().unwrap().next;
    }
