    for _ in 0..length.div_ceil(2) {
        cut = &mut cut.as_mut().unwrap().next;
    }
    let mut rest = cut.take();
    let mut reversed = None;
    while let Some(mut n) = rest {
        rest = n.next.take();
        n.next = reversed;
        reversed = Some(n);
