    while let Some(mut n) = reversed {
        reversed = n.next.take();
        let old = cursor.as_mut().unwrap().next.take();
        n.next = old;
        cursor.as_mut().unwrap().next = Some(n);
        cursor = &mut cursor.as_mut().unwrap().next.as_mut().unwrap().next;
    }
