        for _ in 0..queue.len() {
            let n = queue.pop_front().unwrap();
            sum += n.value;
            if let Some(left) = &n.left {
                queue.push_back(left);
            }
            if let Some(right) = &n.right {
                queue.push_back(right);
            }
        }
        out.push(sum);
    }
    out
}

