fn diameter(root: &Tree) -> usize {
    fn height(root: &Tree, best: &mut usize) -> usize {
        match root {
            None => 0,
            Some(n) => {
                let left = height(&n.left, best);
                let right = height(&n.right, best);
                *best = (*best).max(left + right);
                1 + left.max(right)
            }
        }
    }
    let mut best = 0;
    height(root, &mut best);
    best
}

