    let result = prim_weight(&[
        vec![(1, 1), (2, 4)],
        vec![(0, 1), (2, 2), (3, 5)],
        vec![(0, 4), (1, 2), (3, 3)],
        vec![(1, 5), (2, 3)],
    ])
    .to_string();
    println!("{result}");
}

