struct RollbackDsu {
    parent: Vec<usize>,
    size: Vec<usize>,
    history: Vec<(usize, usize, usize)>,
}
impl RollbackDsu {
    fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
            size: vec![1; n],
            history: Vec::new(),
        }
    }
    fn root(&self, mut v: usize) -> usize {
        while v != self.parent[v] {
            v = self.parent[v];
        }
        v
    }
    fn join(&mut self, a: usize, b: usize) {
