pub fn artifact_matches(
    commit: &str,
    digest: &str,
    expected: &str,
) -> bool {
    let hex = |s: &str, n: usize| {
        s.len() == n
            && s.bytes().all(|b| {
                b.is_ascii_digit() || (b'a'..=b'f').contains(&b)
            })
    };
    hex(commit, 40)
        && hex(digest, 64)
        && hex(expected, 64)
        && digest == expected
}

fn main() {
    assert_eq!(
        artifact_matches(
            &"a".repeat(40),
            &"b".repeat(64),
            &"b".repeat(64)
        ),
        true,
        "case 1"
    );
    assert_eq!(
        artifact_matches("main", &"b".repeat(64), &"b".repeat(64)),
        false,
        "case 2"
    );
    assert_eq!(
        artifact_matches(
            &"a".repeat(40),
            &"b".repeat(64),
            &"c".repeat(64)
        ),
        false,
        "case 3"
    );
    assert_eq!(
        artifact_matches(
            &"A".repeat(40),
            &"b".repeat(64),
            &"b".repeat(64)
        ),
        false,
        "case 4"
    );
    assert_eq!(
        artifact_matches(&"a".repeat(40), "", ""),
        false,
        "case 5"
    );
    println!("worked example passed");
}

